test("both offers apply and the 10 percent discount is charged only on paid units", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 8, unitPrice: 5.00 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 40.00, freeUnits: 2, paidUnits: 6, lineTotal: 27.00 });
});

test("units below 4 get only the 10 percent discount", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 3, unitPrice: 5.00 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 15.00, freeUnits: 0, paidUnits: 3, lineTotal: 13.50 });
});

test("free units are the whole sets of four on the line and leftover units are charged", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 7, unitPrice: 5.00 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 35.00, freeUnits: 1, paidUnits: 6, lineTotal: 27.00 });
});

test("zero units is valid and the normal price is units times unit price", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 0, unitPrice: 5.00 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 0.00, freeUnits: 0, paidUnits: 0, lineTotal: 0.00 });
});

test("negative units are rejected and no total is returned", function () {
  assert.throws(function () {
    code.priceLine({ sku: "SKU1", units: -1, unitPrice: 5.00 });
  }, /invalid field: units/);
});

test("negative unit price is rejected and no total is returned", function () {
  assert.throws(function () {
    code.priceLine({ sku: "SKU1", units: 1, unitPrice: -1 });
  }, /invalid field: unitPrice/);
});

test("the line total is rounded once at the end half up to 2 decimals", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 1, unitPrice: 0.05 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 0.05, freeUnits: 0, paidUnits: 1, lineTotal: 0.05 });
});

test("one free unit is waived in each complete set of four", function () {
  var actual = code.priceLine({ sku: "SKU1", units: 4, unitPrice: 5.00 });
  assert.deepEqual(actual, { sku: "SKU1", normalPrice: 20.00, freeUnits: 1, paidUnits: 3, lineTotal: 13.50 });
});
